using System;

namespace StdbModule;

public static partial class EnglishQuotes
{
    public static class JohnFKennedy
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "The New Frontier of which I speak is not a set of promises — it is a set of challenges. It sums up not what I intend to offer the American people, but what I intend to ask of them.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "War will exist until that distant day when the conscientious objector enjoys the same reputation and prestige that the warrior does today.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "If more politicians knew poetry, and more poets knew politics, I am convinced the world would be a little better place in which to live.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "Let us not despair but act. Let us not seek the Republican answer or the Democratic answer but the right answer. Let us not seek to fix the blame for the past — let us accept our own responsibility for the future.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "Those who make peaceful revolution impossible will make violent revolution inevitable.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "The great revolution in the history of man, past, present and future, is the revolution of those determined to be free.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "I can assure you that every degree of mind and spirit that I possess will be devoted to the long-range interests of the United States and to the cause of freedom around the world.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "I believe in an America that is on the march — an America respected by all nations, friends and foes alike — an America that is moving, doing, working, trying — a strong America in a world of peace. That peace must be based on world law and world order, on the mutual respect of all nations for the rights and powers of others and on a world economy in which no nation lacks the ability to provide a decent standard of living for all of its people.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "This flight was made out in the open with all the possibilities of failure, which would have been damaging to our country's prestige. Because great risks were taken in that regard, it seems to me that we have some right to claim that this open society of ours which risked much, gained much.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "We sometimes chafe at the burden of our obligations, the complexity of our decisions, the agony of our choices. But there is no comfort or security for us in evasion, no solution in abdication, no relief in irresponsibility.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "Change is the law of life. And those who look only to the past or the present are certain to miss the future.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "Although a country may stand still, history never stands still. Thus, if we do not soon begin to move forward again, we will inevitably be left behind. … But effort and courage are not enough without purpose and direction. For, as Socrates told us, \"If a man does not know to what port he is sailing, no wind is favorable.\"", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "Across the gulfs and barriers that now divide us, we must remember that there are no permanent enemies. Hostility today is a fact, but it is not a ruling law. The supreme reality of our time is our indivisibility as children of God and our common vulnerability on this planet.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "Our progress as a nation can be no swifter than our progress in education. … The human mind is our fundamental resource.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "The great enemy of the truth is very often not the lie — deliberate, contrived and dishonest — but the myth — persistent, persuasive, and unrealistic.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "A man may die, nations may rise and fall, but an idea lives on. Ideas have endurance without death.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "In a democracy, every citizen, regardless of his interest in politics, 'hold office'; everyone of us is in a position of responsibility; and, in the final analysis, the kind of government we get depends upon how we fulfill those responsibilities. We, the people, are the boss, and we will get the kind of political leadership, be it good or bad, that we demand and deserve.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "In a world of danger and trial, peace is our deepest aspiration … But it is an unfortunate fact that we can secure peace only by preparing for war.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "The courage of life is often a less dramatic spectacle than the courage of a final moment; but it is no less a magnificent mixture of triumph and tragedy. A man does what he must — in spite of personal consequences, in spite of obstacles and dangers, and pressures — and that is the basis of all human morality.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "Things don't just happen, they are made to happen.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "The world was not meant to be a prison in which man awaits his execution.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "Where in the hell have you guys been? I've been at this bus stop for a whole week now.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "After visiting such Nazi strongholds as were found in Berchtesgaden and Obersalzberg; he had boundless ambition for his country which rendered him a menace to the peace of the world, but he had a mystery about him in the way that he lived and in the manner of his death that will live and grow after him. He had in him the stuff of which legends are made.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "They follow the Hitler line – no matter how big the lie, repeat it often enough and the masses will regard it as truth.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "In the Chinese language, the word \"crisis\" is composed of two characters, one representing danger and the other, opportunity.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "We should not be too hasty in condemning all compromise as bad morals. For politics and legislation are not matters for inflexible principles or unattainable ideals.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "The voters selected us, in short, because they had confidence in our judgement and our ability to exercise that judgement from a position where we could determine what were their own best interest, as a part of the nation's interest. This may mean that we must on occasion lead, inform, correct and sometimes even ignore constituent opinion, if we are to exercise fully that judgment for which we were elected.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "We shall need compromises in the days ahead, to be sure. But these will be, or should be, compromises of issues, not of principles. We can compromise our political positions, but not ourselves... Compromise does not mean cowardice.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "The true democracy, living and growing and inspiring, puts its faith in the people — faith that the people will not simply elect men who will represent their views ably and faithfully, but will also elect men who will exercise their conscientious judgment — faith that the people will not condemn those whose devotion to principle leads them to unpopular courses, but will reward courage, respect honor, and ultimately recognize right.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "For in a democracy, every citizen, regardless of his interest in politics, 'hold office'; everyone of us is in a position of responsibility; and, in the final analysis, the kind of government we get depends upon how we fulfill those responsibilities. We, the people, are the boss, and we will get the kind of political leadership, be it good or bad, that we demand and deserve.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "The courage of life is often a less dramatic spectacle than the courage of a final moment; but it is no less a magnificent mixture of triumph and tragedy. A man does what he must — in spite of personal consequences, in spite of obstacles and dangers, and pressures — and that is the basis of all human morality.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "The stories of past courage can define that ingredient — they can teach, they can offer hope, they can provide inspiration. But they cannot supply courage itself. For this each man must look into his own soul.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "Senators, we hear, must be politicians – and politicians must be concerned only with winning votes, not with statesmanship or courage. Mothers may still want their favorite sons to grow up to be President, but according to a famous Gallup poll of some years ago, they do not want them to become politicians in the process.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "Perhaps if the American people more fully comprehended the terrible pressures which discourage acts of political courage, which drive a Senator to abandon or subdue his conscience, then they might be less critical of those who take the easier road - and more appreciative of those still able to follow the path of courage.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "The first pressure to be mentioned is a form of pressure rarely recognized by the general public. Americans want to be liked – and Senators are no exception... We prefer praise to abuse, popularity to contempt... we are anxious to get along with our fellow legislators, our fellow members of the club, to abide by clubhouse rules and patterns... “The way to get along,” I was told when I entered Congress, “is to go along.”", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "Going along means more than just good fellowship – it includes the use of compromise, the sense of things possible. We should not be too hasty in condemning all compromise as bad morals. For politics and legislation are not matters for inflexible principles or unattainable ideals.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "Some of my colleagues who are criticized today for lack of forthright principles – or who are looked upon with scornful eyes as compromising “politicians” – are simply engaged in the fine art of conciliating, balancing and interpreting the forces and factions of public opinion, an art essential to keeping our nation united and enabling our Government to function.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "But the question is how we will compromise and with whom. For it is easy to seize upon unnecessary concessions, not as means of legitimately resolving conflicts but as methods of “going along.”", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "It is thinking of the next campaign – the desire to be re-elected – that provides the second pressure on the conscientious Senator...", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "Defeat, moreover, is not only a setback for the Senator himself – he is also obligated to consider the effect upon the party he supports, upon the friends and supporters who have “gone out on a limb” for him or invested their savings in his career, and even upon the wife and children whose happiness and security – often depending at least in part upon his success in office – may mean more to him than anything else. Where else, in a non-totalitarian country, but in the political profession is the individual expected to sacrifice all – including his own career – for the national good? ... Lawyers, businessmen, teachers, doctors, all face difficult personal decisions involving their integrity – but few, if any, face them in the glare of the spotlight as do those in public office. Few, if any, face the same dread finality of decision that confronts a Senator facing an important call of the roll. He may want more time for his decision – he may believe there is something to be said for both sides – he may feel that a slight amendment could remove all difficulties – but when that roll is called he cannot hide, he cannot equivocate, he cannot delay, like the Raven in Poe’s poem, is perched there on his Senate desk, croaking “Nevermore” as he casts the vote that stakes his political future.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "Not all Senators would agree – but few would deny that the desire to be re-elected exercises a strong brake on independent courage. The third and most significant source of pressures which discourage political courage in the conscientious Senator or Congressman – and practically all of the problems described in this chapter apply equally to members of both Houses - is the pressure of his constituency, the interest groups, the organized letter writers, the economic blocs and even the average voter.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "If we tell our constituents frankly that we can do nothing, they feel we are unsympathetic or inadequate. If we try and fail – usually meeting a counteraction from other Senators representing other interests – they say we are like all the rest of the politicians... We may tell ourselves that these pressure groups and letter writers represent only a small percentage of the voters – and this is true. But they are the articulate few whose views cannot be ignored and who constitute the greater part of our contacts with the public at large, whose opinions we cannot know, whose vote we must obtain and yet who in all probability have a limited idea of what we are trying to do.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "But there is no real problem, some will say. Always do what is right, regardless of whether it is popular. . . . That is an easy answer – but it is easy only for those who do not bear the responsibilities of elected office. . . . Are we rightfully entitled to ignore the demands of our constituents even if we are able and willing to do so?", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "And if such interests are ever to be abandoned in favor of the national good, let the constituents – not the Senator – decide when and to what extent. For he is their agent in Washington, the protector of their rights, recognized by the Vice President in the Senate Chamber as “the Senator from Massachusetts” or “the Senator from Texas.”", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "But when all of this is said and admitted, we have not yet told the full story. For in Washington we are “United States Senators” and members of the Senate of the United States as well as Senators form Massachusetts and Texas. Our oath of office is administered by the Vice President, not by the Governors of our respective states; we come to Washington, to paraphrase Edmund Burke, not as hostile ambassadors or special pleaders for our state or section, in opposition to advocates and agents of other areas, but as members of the deliberative assembly of one nation with one interest.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "There are other obligations in addition to those of state and region – the obligations of the party whose pressures have already been described. Even if I can disregard those pressures, do I not have an obligation to go along with the party that placed me in office? We believe in this country in the principle of party responsibility, and we recognize the necessity of adhering to party platforms – if the party label is to mean anything to the voters.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "But when party and officeholder differ as to how the national interest is to be served, we must place first the responsibility we owe not to our party or even to our constituents, but to our individual consciences.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "But it is a little easier to dismiss one’s obligations to local interests and party ties than to face squarely the problem of one’s responsibility to the will of his constituents. A Senator who avoids this responsibility would appear to be accountable to no one, and the basic safeguards of our democratic system would thus have vanished. He is no longer representative in the true sense, he has violated public trust, he has betrayed the confidence demonstrated by those who voted for him to carry out their views.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "The voters selected us, in short, because they had confidence in our judgment and our ability to exercise that judgment from a position where we could determine what were their own best interests, as a part of the nation's interest. This may mean that we must on occasion lead, inform, correct and sometimes even ignore constituent opinion, if we are to exercise fully that judgment for which we were elected.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "Today the challenge of political courage looms larger than ever before. For our everyday life is becoming so saturated with the tremendous power of mass communications that any unpopular or unorthodox course arouses a storm of protests such as John Quincy Adams could never have envisioned.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "Our political life is becoming so expensive, so mechanized and so dominated by professional politicians and public relations men that the idealist who dreams of independent statesmanship is rudely awakened by the necessities of election and accomplishment...", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "And thus, in the days ahead, only the very courageous will be able to take the hard and unpopular decisions necessary for our survival in the struggle with a powerful enemy – an enemy with leaders who need give little thought to the popularity of their course, who need pay little tribute to the public opinion they themselves manipulate, and who may force, without fear of retaliation at the polls, their citizens to sacrifice present laughter for future glory.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "We shall need compromises in the days ahead, to be sure. But these will be, or should be, compromises of issues, not of principles. We can compromise our political positions, but not ourselves... Compromise does not mean cowardice. Indeed it is frequently the compromisers and conciliators who are faced with the severest tests of political courage as they oppose the extremist views of their constituents.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "Only the very courageous will be able to keep alive the spirit of individualism and dissent which gave birth to this nation, nourished it as an infant, and carried it through its severest tests upon the attainment of its maturity.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "We celebrate the past to awaken the future.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "the Communists are determined to destroy us, and regardless of what hand of friendship we may hold out or what arguments we may put up, the only thing that will make that decisive difference is the strength of the United States.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "Now let me make it clear that I believe there can only be one defense policy for the United States and that is summed up in the word 'first.' I do not mean 'first, but'. I do not mean 'first, when'. I do not mean 'first, if'. I mean 'first — period'.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "In a world of danger and trial, peace is our deepest aspiration, and when peace comes we will gladly convert not our swords into plowshares, but our bombs into peaceful reactors, and our planes into space vessels. \"Pursue peace,\" the Bible tells us, and we shall pursue it with every effort and every energy that we possess. But it is an unfortunate fact that we can secure peace only by preparing for war.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "That requires only one kind of defense policy, a policy summed up in a single word \"first.\" I do not mean \"first, if,\" I do not mean \"first, but,\" I do not mean \"first, when,\" but I mean \"First, period.\"", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "My call is not to those who believe they belong to the past. My call is to those who believe in the future.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "although a country may stand still, history never stands still. Thus, if we do not soon begin to move forward again, we will inevitably be left behind. And I know that Americans today are tired of standing still — and that we do not intend to be left behind. But effort and courage are not enough without purpose and direction. For, as Socrates told us, \"If a man does not know to what port he is sailing, no wind is favorable.\"", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "our own greatness is living proof that the road to abundance is freedom's road. And we intend to build a still greater America where every man has a chance to work, a decent house to live in and decent schools for his children because we believe in a decent life for all our citizens - and because we who first lit man's hope for the good life are determined that freedom shall continue to show the way to progress.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "only an America which is applying its full resources of imagination and thought and strength to the resolution of the world's great problems - only such an America will be able to maintain its position as the champion of peace and the protector of freedom everywhere.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "only a stronger America can hope to maintain its freedom and the freedom of the world. We are faced with an enemy which now commands a vast empire from the Formosa Straits to Berlin - an enemy whose agents of subversion are penetrating into Africa, into Asia, and now stand only ninety miles from our shores in Cuba - an enemy which is convinced of its ultimate victory - which believes, to quote Mr. Khrushchev, \"that the old and the rotten will always fight with the newly emerged, but it is a law of history that the new will always win.\" But it is freedom that is new, and despotism and tyranny that is as old as civilization is - and it is freedom that will win - not because of any law of history - but because we will have the strength and the determination that will bring the victory.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "I think the basic problem facing the United States is to maintain the peace, maintain our vital interest in our national security, serve as the leader of the cause of freedom around the globe, and attempt to develop in this country sufficient forward motion so that we catch again the imagination of the world as a power and a system of government that represents the kind of government which all people want to endorse, the kind of government under which all people want to live. In other words, if we do well here, we enhance the prestige and power and influence of the cause of freedom around the world. If we fail, the cause of freedom fails. If we succeed, the cause of freedom succeeds. Our responsibility is to throw light and luster around that great cause, around the globe.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "There is a connection, hard to explain logically but easy to feel, between achievement in public life and progress in the arts. The age of Pericles was also the age of Phidias. The age of Lorenzo de Medici was also the age of Leonardo da Vinci. The age of Elizabeth was also the age of Shakespeare. And the New Frontier for which I campaign in public life, can also be a New Frontier for American art.", Author = "John F. Kennedy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_F._Kennedy", Text = "If by a \"Liberal\" they mean someone who looks ahead and not behind, someone who welcomes new ideas without rigid reactions, someone who cares about the welfare of the people — their health, their housing, their schools, their jobs, their civil rights, and their civil liberties — someone who believes we can break through the stalemate and suspicions that grip us in our policies abroad, if that is what they mean by a \"Liberal,\" then I'm proud to say I'm a \"Liberal.\"", Author = "John F. Kennedy" },
        };
    }
}